#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
# SPDX-FileCopyrightText: 2026 The Linux Foundation
##############################################################################
# For every project/env, the lowercase ${key} references in the rendered
# JCasC (secrets read from $SECRETS/<key>), plus direct
# /run/secrets/jcasc/<key> paths, must be listed in
# projects/<project>/secret-keys.txt, and every listed key must be used.
# ci-admin-password is generated by the CI test, not stored in 1Password.
#
# Usage: scripts/check-secret-keys.sh
##############################################################################

set -euo pipefail
# shellcheck source=scripts/lib.sh
source "$(dirname "$0")/lib.sh"
need kustomize yq

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
rc=0

for pdir in "$REPO_ROOT"/projects/*/; do
  project="$(basename "$pdir")"
  secret_keys "$project" | sort -u > "$work/declared"
  : > "$work/used-all"
  for edir in "$pdir"envs/*/; do
    env="$(basename "$edir")"
    rm -rf "$work/r"
    render_env_dir "$project" "$env" "$work/r"
    # ${key} references (^${...} is an escaped literal) and direct file
    # paths under the secrets mount; comment lines are ignored.
    grep -hvE '^[[:space:]]*#' "$work/r/casc/"*.yaml \
      | grep -oE '(^|[^^])\$\{[a-z][a-z0-9-]*\}|/run/secrets/jcasc/[a-z][a-z0-9-]*' \
      | sed -E -e 's/.*\$\{([^}]*)\}/\1/' -e 's|.*/run/secrets/jcasc/||' \
      | sort -u | grep -vx 'ci-admin-password' > "$work/used" || true
    cat "$work/used" >> "$work/used-all"
    missing="$(comm -23 "$work/used" "$work/declared")"
    if [[ -n "$missing" ]]; then
      echo "ERROR: $project/$env uses keys missing from secret-keys.txt: $missing" >&2
      rc=1
    fi
  done
  unused="$(comm -13 <(sort -u "$work/used-all") "$work/declared")"
  if [[ -n "$unused" ]]; then
    echo "ERROR: $project secret-keys.txt lists unused keys: $unused" >&2
    rc=1
  fi
  ((rc)) || log "$project: $(wc -l < "$work/declared") secret keys match JCasC"
done
exit "$rc"
